// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListAssets 查询资产登记
	// (GET /assets)
	ListAssets(c *gin.Context, params ListAssetsParams)
	// UpsertAsset 创建/更新资产登记（MAC 幂等 upsert）
	// (PUT /assets)
	UpsertAsset(c *gin.Context)
	// DeleteAsset 删除资产登记
	// (DELETE /assets/{mac})
	DeleteAsset(c *gin.Context, mac string)
	// ListBlocklists 查询封禁名单库
	// (GET /dns/blocklists)
	ListBlocklists(c *gin.Context)
	// CreateBlocklist 创建名单库
	// (POST /dns/blocklists)
	CreateBlocklist(c *gin.Context)
	// SyncBlocklist 订阅源同步（失败保留旧版）
	// (POST /dns/blocklists/{listId})
	SyncBlocklist(c *gin.Context, listId openapi_types.UUID)
	// ListBlocklistEntries 查询名单条目
	// (GET /dns/blocklists/{listId}/entries)
	ListBlocklistEntries(c *gin.Context, listId openapi_types.UUID, params ListBlocklistEntriesParams)
	// AddBlocklistEntry 添加条目
	// (POST /dns/blocklists/{listId}/entries)
	AddBlocklistEntry(c *gin.Context, listId openapi_types.UUID)
	// FlushCache 清空缓存（全部或指定 zone）
	// (POST /dns/cache/flush)
	FlushCache(c *gin.Context)
	// ListPolicyGroups 查询策略分组
	// (GET /dns/policy-groups)
	ListPolicyGroups(c *gin.Context)
	// CreatePolicyGroup 创建策略分组（view 唯一）
	// (POST /dns/policy-groups)
	CreatePolicyGroup(c *gin.Context)
	// CompilePolicyGroup 增量编译该分组的 RPZ zone 并单区刷新
	// (POST /dns/policy-groups/{groupId}/compile)
	CompilePolicyGroup(c *gin.Context, groupId openapi_types.UUID)
	// GetDnsSettings 查询 DNS 行为参数（缓存+安全）
	// (GET /dns/settings)
	GetDnsSettings(c *gin.Context)
	// UpdateDnsSettings 更新 DNS 行为参数（渲染→checkconf→reload）
	// (PUT /dns/settings)
	UpdateDnsSettings(c *gin.Context)
	// ListTtlOverrides 查询每域名 TTL 覆盖列表
	// (GET /dns/settings/ttl-overrides)
	ListTtlOverrides(c *gin.Context)
	// UpsertTtlOverride 设置或更新域名 TTL 覆盖（reload 生效）
	// (PUT /dns/settings/ttl-overrides)
	UpsertTtlOverride(c *gin.Context)
	// ListDnsZones 查询本地区域
	// (GET /dns/zones)
	ListDnsZones(c *gin.Context)
	// CreateDnsZone 创建本地区域
	// (POST /dns/zones)
	CreateDnsZone(c *gin.Context)
	// DeleteDnsZone 删除区域（级联记录）
	// (DELETE /dns/zones/{zoneId})
	DeleteDnsZone(c *gin.Context, zoneId ZoneId)
	// ExportDnsZone 导出 zonefile（checkconf 校验过的静态区）
	// (GET /dns/zones/{zoneId})
	ExportDnsZone(c *gin.Context, zoneId ZoneId)
	// ListLinkedRecords 联动记录（只读）
	// (GET /dns/zones/{zoneId}/linked)
	ListLinkedRecords(c *gin.Context, zoneId ZoneId)
	// ListDnsRecords 查询区域记录
	// (GET /dns/zones/{zoneId}/records)
	ListDnsRecords(c *gin.Context, zoneId ZoneId)
	// CreateDnsRecord 创建记录（触发 auth_zone_reload 单区刷新）
	// (POST /dns/zones/{zoneId}/records)
	CreateDnsRecord(c *gin.Context, zoneId ZoneId)
	// ListForwardRules 查询条件转发规则
	// (GET /forward-rules)
	ListForwardRules(c *gin.Context)
	// CreateForwardRule 创建条件转发规则（最长后缀优先）
	// (POST /forward-rules)
	CreateForwardRule(c *gin.Context)
	// DeleteForwardRule 删除转发规则（forward_remove）
	// (DELETE /forward-rules/{ruleId})
	DeleteForwardRule(c *gin.Context, ruleId openapi_types.UUID)
	// UpdateForwardRule 更新转发规则（重新下发）
	// (PATCH /forward-rules/{ruleId})
	UpdateForwardRule(c *gin.Context, ruleId openapi_types.UUID)
	// ListLedger 查询地址台账（六态矩阵）
	// (GET /ledger)
	ListLedger(c *gin.Context, params ListLedgerParams)
	// ReserveAddress 地址转保留（冻结不下发）
	// (POST /ledger)
	ReserveAddress(c *gin.Context)
	// BindStatic 地址转静态绑定（MAC 锚定）
	// (POST /ledger/bind)
	BindStatic(c *gin.Context)
	// ListOrgTree 查询组织分组树
	// (GET /orgs)
	ListOrgTree(c *gin.Context)
	// CreateOrg 创建组织分组节点
	// (POST /orgs)
	CreateOrg(c *gin.Context)
	// DeleteOrg 删除空组织节点
	// (DELETE /orgs/{orgId})
	DeleteOrg(c *gin.Context, orgId OrgId)
	// UpdateOrg 改名与/或移动组织节点
	// (PATCH /orgs/{orgId})
	UpdateOrg(c *gin.Context, orgId OrgId)
	// BulkReservations 批量创建保留与静态绑定（CSV 语义，事务性）
	// (POST /reservations/bulk)
	BulkReservations(c *gin.Context)
	// ListSubnets 查询子网列表
	// (GET /subnets)
	ListSubnets(c *gin.Context, params ListSubnetsParams)
	// CreateSubnet 创建子网与地址池
	// (POST /subnets)
	CreateSubnet(c *gin.Context)
	// DeleteSubnet 删除子网（级联池）
	// (DELETE /subnets/{subnetId})
	DeleteSubnet(c *gin.Context, subnetId SubnetIdParam)
	// UpdateSubnet 更新子网（改名/调整池）
	// (PATCH /subnets/{subnetId})
	UpdateSubnet(c *gin.Context, subnetId SubnetIdParam)
	// GetSystemInfo 查询控制面系统信息
	// (GET /system/info)
	GetSystemInfo(c *gin.Context)
	// ListUpstreams 查询上游服务器（含探活状态）
	// (GET /upstreams)
	ListUpstreams(c *gin.Context)
	// CreateUpstream 创建上游（触发 forward-zone 下发）
	// (POST /upstreams)
	CreateUpstream(c *gin.Context)
	// DeleteUpstream 删除上游（forward_remove）
	// (DELETE /upstreams/{upstreamId})
	DeleteUpstream(c *gin.Context, upstreamId openapi_types.UUID)
	// UpdateUpstream 更新上游（重新下发）
	// (PATCH /upstreams/{upstreamId})
	UpdateUpstream(c *gin.Context, upstreamId openapi_types.UUID)
}

